import React, { useState, useEffect, useRef } from 'react';
import Dashboard from './Dashboard';
import Enrollment from './Enrollment';
import CameraRecognition from './CameraRecognition';
import Login from './pages/Login';
import authService from './auth_service';
import { studentsAPI } from './api_service';

const COLORS = {
  primary: '#4F46E5',
  background: '#F8FAFC',
  surface: '#FFFFFF',
  textMain: '#1E293B',
  textMuted: '#64748B',
  border: '#E2E8F0',
  sidebar: '#1E293B'
};

const App = () => {
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const [currentUser, setCurrentUser] = useState(null);
  const [currentView, setCurrentView] = useState('dashboard');
  const [notifications, setNotifications] = useState([]);
  const [loading, setLoading] = useState(true);

  // ================= SEARCH STATES =================
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState([]);
  const [showResults, setShowResults] = useState(false);

  const debounceRef = useRef(null);

  // ================= INIT AUTH =================
  useEffect(() => {
    authService.initialize();

    if (authService.isAuthenticated()) {
      setCurrentUser(authService.getUser());
      setIsAuthenticated(true);
    }

    setLoading(false);
  }, []);

  // ================= NOTIFICATIONS =================
  const addNotification = (message, type = 'info') => {
    const id = Date.now();
    setNotifications(prev => [...prev, { id, message, type }]);

    setTimeout(() => {
      setNotifications(prev => prev.filter(n => n.id !== id));
    }, 4000);
  };

  // ================= SEARCH WITH DEBOUNCE =================
  const handleSearch = (value) => {
    setSearchQuery(value);

    if (debounceRef.current) {
      clearTimeout(debounceRef.current);
    }

    if (value.trim().length < 2) {
      setSearchResults([]);
      setShowResults(false);
      return;
    }

    debounceRef.current = setTimeout(async () => {
      try {
        const results = await studentsAPI.search(value);
        setSearchResults(results || []);
        setShowResults(true);
      } catch (error) {
        console.error(error);
        addNotification('❌ Erreur de recherche serveur', 'error');
      }
    }, 400); // ⏱ debounce 400ms
  };

  // ================= SELECT RESULT =================
  const handleSelectStudent = (student) => {
    setSearchQuery(student.name || student.full_name || '');
    setShowResults(false);
    addNotification(`👤 Étudiant sélectionné: ${student.name}`, 'info');
  };

  // ================= LOGIN =================
  const handleLoginSuccess = (user) => {
    setCurrentUser(user);
    setIsAuthenticated(true);
    addNotification(`✅ Bienvenue ${user.first_name || user.username}`, 'success');
  };

  // ================= LOGOUT =================
  const handleLogout = async () => {
    await authService.logout();
    setCurrentUser(null);
    setIsAuthenticated(false);
    setSearchQuery('');
    setSearchResults([]);
    addNotification('👋 Déconnexion réussie', 'info');
  };

  if (loading) {
    return <div style={styles.loading}>⏳ Chargement...</div>;
  }

  if (!isAuthenticated) {
    return <Login onLoginSuccess={handleLoginSuccess} />;
  }

  return (
    <div style={styles.appWrapper}>

      {/* ================= SIDEBAR ================= */}
      <aside style={styles.sidebar}>
        <div style={styles.brand}>
          <div style={styles.brandIcon}>Σ</div>
          <h2 style={styles.brandName}>Attendance OS</h2>
        </div>

        <nav style={styles.sideNav}>
          <NavItem active={currentView === 'dashboard'} onClick={() => setCurrentView('dashboard')} icon="📊" label="Dashboard" />
          <NavItem active={currentView === 'enrollment'} onClick={() => setCurrentView('enrollment')} icon="➕" label="Enrôlement" />
          <NavItem active={currentView === 'camera'} onClick={() => setCurrentView('camera')} icon="📷" label="Reconnaissance" />
        </nav>

        <button onClick={handleLogout} style={styles.logoutBtn}>
          🚪 Déconnexion
        </button>
      </aside>

      {/* ================= MAIN ================= */}
      <main style={styles.main}>

        {/* TOP BAR */}
        <header style={styles.topBar}>

          {/* SEARCH */}
          <div style={{ position: 'relative', width: 420 }}>
            <div style={styles.searchBar}>
              🔍
              <input
                style={styles.searchInput}
                value={searchQuery}
                onChange={(e) => handleSearch(e.target.value)}
                onFocus={() => searchResults.length > 0 && setShowResults(true)}
                placeholder="Rechercher un étudiant..."
              />
            </div>

            {/* DROPDOWN RESULTS */}
            {showResults && searchResults.length > 0 && (
              <div style={styles.dropdown}>
                {searchResults.map((student, index) => (
                  <div
                    key={index}
                    style={styles.resultItem}
                    onClick={() => handleSelectStudent(student)}
                  >
                    <div style={{ fontWeight: 600 }}>
                      {student.name || student.full_name}
                    </div>
                    <div style={{ fontSize: 12, color: '#64748B' }}>
                      ID: {student.id}
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>

        </header>

        {/* CONTENT */}
        <div style={styles.content}>
          {currentView === 'dashboard' && <Dashboard />}
          {currentView === 'enrollment' && <Enrollment />}
          {currentView === 'camera' && <CameraRecognition />}
        </div>
      </main>

      {/* NOTIFICATIONS */}
      <div style={styles.toastContainer}>
        {notifications.map(n => (
          <div key={n.id} style={styles.toast}>
            {n.message}
          </div>
        ))}
      </div>

    </div>
  );
};

// ================= NAV ITEM =================
const NavItem = ({ active, icon, label, onClick }) => (
  <div onClick={onClick} style={{
    padding: 12,
    cursor: 'pointer',
    color: active ? '#4F46E5' : '#94A3B8',
    fontWeight: 500
  }}>
    {icon} {label}
  </div>
);

// ================= STYLES =================
const styles = {
  loading: { height: '100vh', display: 'grid', placeItems: 'center' },

  appWrapper: { display: 'flex' },

  sidebar: {
    width: 260,
    background: '#1E293B',
    color: 'white',
    height: '100vh',
    padding: 20
  },

  brand: { display: 'flex', gap: 10, marginBottom: 30 },

  brandIcon: {
    width: 40,
    height: 40,
    background: '#4F46E5',
    display: 'grid',
    placeItems: 'center',
    borderRadius: 8
  },

  searchBar: {
    display: 'flex',
    gap: 10,
    padding: 10,
    background: '#F1F5F9',
    borderRadius: 8
  },

  searchInput: {
    border: 'none',
    width: '100%',
    outline: 'none',
    background: 'transparent'
  },

  dropdown: {
    position: 'absolute',
    top: 45,
    width: '100%',
    background: 'white',
    border: '1px solid #E2E8F0',
    borderRadius: 8,
    maxHeight: 250,
    overflowY: 'auto',
    zIndex: 999
  },

  resultItem: {
    padding: 10,
    cursor: 'pointer',
    borderBottom: '1px solid #F1F5F9'
  },

  main: { flex: 1 },

  topBar: {
    padding: 20,
    background: 'white',
    borderBottom: '1px solid #E2E8F0'
  },

  content: { padding: 20 },

  logoutBtn: {
    marginTop: 20,
    background: '#EF4444',
    color: 'white',
    border: 'none',
    padding: 10,
    width: '100%',
    borderRadius: 6
  },

  toastContainer: {
    position: 'fixed',
    bottom: 20,
    right: 20
  },

  toast: {
    background: '#1E293B',
    color: 'white',
    padding: 10,
    marginTop: 8,
    borderRadius: 6
  }
};

export default App;
